import json
from pathlib import Path
from typing import Any, Dict


def load_config(config_file: str, defaults: Dict[str, Any]) -> Dict[str, Any]:
    """Load configuration from JSON file with fallback to defaults."""
    config_path = Path(config_file)

    if config_path.exists():
        try:
            with open(config_path) as f:
                return json.load(f)
        except (json.JSONDecodeError, IOError):
            pass

    return defaults.copy()


class Config:
    """Configuration manager with file loading and defaults fallback."""

    def __init__(self, filepath: str, defaults: Dict[str, Any] | None = None):
        self.filepath = Path(filepath)
        self.defaults = defaults or {}
        self.data = self._load()

    def _load(self) -> Dict[str, Any]:
        """Load and return configuration dictionary."""
        if not self.filepath.exists():
            return self.defaults.copy()

        try:
            with open(self.filepath) as f:
                return json.load(f)
        except (json.JSONDecodeError, IOError):
            return self.defaults.copy()

    def get(self, key: str, default: Any = None) -> Any:
        """Retrieve configuration value with optional default."""
        return self.data.get(key, default)

    def __getitem__(self, key: str) -> Any:
        return self.data[key]

    def reload(self) -> None:
        """Refresh configuration from disk."""
        self.data = self._load()


if __name__ == "__main__":
    defaults = {
        "debug": False,
        "host": "localhost",
        "port": 8000,
        "timeout": 30,
    }

    config = Config("config.json", defaults)
    print(f"Debug: {config.get('debug')}")
    print(f"Port: {config['port']}")
